float len(V a) { return sqrt(dot(a,a)); }
V norm(V a) { return div(a, len(a)); }
V cross(V a, V b) { return (V){a.y*b.z-a.z*b.y, a.z*b.x-a.x*b.z, a.x*b.y-a.y*b.x}; }

int main() {
    int w=2400, h=1800;
    FILE *f = fopen("reconstructed.ppm", "w");
    fprintf(f, "P3\n%d %d\n255\n", w, h);

    // Camera at origin looking forward
    V cam = {1200, 900, -2000};
    V light = {1300, 600, -1500};
    V sphere_center = {1200, 993, 100};
    float sphere_radius = 190;

    for (int y = 0; y < h; y++) {
        for (int x = 0; x < w; x++) {
            // Generate ray from camera through pixel
            V ray_dir = norm((V){x - cam.x, y - cam.y, 2000});

            // Sky gradient (blue)
            float sky_r = 146 + (y/1800.0f)*6;
            float sky_g = 190 + (y/1800.0f)*6;
            float sky_b = 255;

            float out_r = sky_r, out_g = sky_g, out_b = sky_b;

            // Ray-sphere intersection
            V oc = sub(cam, sphere_center);
            float a = dot(ray_dir, ray_dir);
            float b = 2.0f * dot(oc, ray_dir);
            float c = dot(oc, oc) - sphere_radius * sphere_radius;
            float discriminant = b*b - 4*a*c;

            if (discriminant >= 0) {
                float t = (-b - sqrt(discriminant)) / (2.0f*a);
                if (t > 0.1f) {
                    // Hit sphere
                    V hit = add(cam, mul(ray_dir, t));
                    V normal = norm(sub(hit, sphere_center));
                    V to_light = norm(sub(light, hit));

                    float diffuse = fmax(0.0f, dot(normal, to_light));
                    float ambient = 0.2f;
                    float brightness = ambient + 0.8f * diffuse;

                    out_r = 51 * brightness;
                    out_g = 10 * brightness;
                    out_b = 10 * brightness;
                }
            } else if (y > 1180) {
                // Floor checkerboard - need to compute floor plane intersection
                // Floor is at z = 1000 (roughly)
                float t_floor = (1000 - cam.z) / ray_dir.z;
                if (t_floor > 0.1f) {
                    V floor_hit = add(cam, mul(ray_dir, t_floor));

                    // Determine checkerboard pattern
                    // Pattern repeats every 200 pixels (100x100 in image = 100x100 in 3D)
                    int pattern_x = (int)(floor_hit.x / 100) % 2;
                    int pattern_z = (int)(floor_hit.z / 100) % 2;

                    int is_light = (pattern_x + pattern_z) % 2;

                    if (is_light) {
                        out_r = 152;
                        out_g = 152;
                        out_b = 152;
                    } else {
                        out_r = 67;
                        out_g = 67;
                        out_b = 67;
                    }
                }
            }

            fprintf(f, "%d %d %d\n", (int)out_r, (int)out_g, (int)out_b);
        }
    }
    fclose(f);
    return 0;
}
